def _parse_time(time_str):
    """Best-effort parse of a free-text time (e.g. '6:00 PM', '18:00') into 'HH:MM:SS'. Returns None if unparseable/blank."""
    if not time_str:
        return None
    from datetime import datetime as _dt
    for fmt in ("%I:%M %p", "%I %p", "%H:%M", "%H:%M:%S"):
        try:
            return _dt.strptime(time_str.strip(), fmt).strftime("%H:%M:%S")
        except ValueError:
            continue
    return None

