def render_editable_squad_table(label, manual_key, fixture_counts, value_col, key_prefix, ascending=False, highlight_threshold=None):
    """Editable, always-full-roster table (like Disciplinary Strikes) reusable for goals/assists/etc."""
    manual = load_manual_tally(manual_key)
    counts = dict(fixture_counts)
    for initials, amount in manual.items():
        counts[initials] = counts.get(initials, 0) + amount

    st.subheader(f"Add {value_col.lower()}")
    col1, col2, col3, col4 = st.columns([2, 1, 1, 1])
    with col1:
        player_input = st.text_input("Player initials (e.g. JB)", key=f"{key_prefix}_player")
    with col2:
        amount_input = st.number_input(f"{value_col} to add/remove", value=1, min_value=1, step=1, key=f"{key_prefix}_amount")
    with col3:
        st.write("")
        st.write("")
        if st.button("Add to table", key=f"{key_prefix}_btn"):
            if player_input.strip():
                add_manual_tally(manual_key, player_input.strip(), amount_input)
                st.rerun()
    with col4:
        st.write("")
        st.write("")
        if st.button("Remove from table", key=f"{key_prefix}_remove_btn"):
            if player_input.strip():
                add_manual_tally(manual_key, player_input.strip(), -amount_input)
                st.rerun()

    with st.expander(f"Reset a player's {value_col.lower()} to 0"):
        reset_col1, reset_col2 = st.columns([2, 1])
        with reset_col1:
            reset_player = st.text_input("Player initials", key=f"{key_prefix}_reset_player")
        with reset_col2:
            st.write("")
            st.write("")
            if st.button("Reset to 0", key=f"{key_prefix}_reset_btn"):
                if reset_player.strip():
                    initials = reset_player.strip()
                    fixture_amount = fixture_counts.get(initials, 0)
                    manual_data = load_manual_tally(manual_key)
                    # Set manual offset so total (fixture + manual) becomes 0
                    manual_data[initials] = -fixture_amount
                    kv_set(manual_key, manual_data)
                    st.rerun()

    roster_rows = [
        {"Initials": initials, "Player": name, value_col: counts.get(initials, 0)}
        for initials, name in SQUAD_ROSTER.items()
    ]
    for initials in counts:
        if initials not in SQUAD_ROSTER:
            roster_rows.append({"Initials": initials, "Player": "(not in roster)", value_col: counts[initials]})

    df = pd.DataFrame(roster_rows).sort_values(
        [value_col, 'Player'], ascending=[ascending, True]
    ).reset_index(drop=True)

    rows_html = "".join(
        f'<tr style="background:{"#C0392B" if highlight_threshold and row[value_col] >= highlight_threshold else ("#FFFFFF" if idx % 2 == 0 else "#F0F0F0")};'
        f'color:{"#FFFFFF" if highlight_threshold and row[value_col] >= highlight_threshold else "#001C58"};">'
        f'<td style="padding:10px 16px;text-align:left;font-weight:600;">{row["Player"]} ({row["Initials"]})</td>'
        f'<td style="padding:10px 16px;text-align:center;">{row[value_col]}</td></tr>'
        for idx, row in df.iterrows()
    )
    html = (
        '<div style="background:#00285E;border-radius:6px;overflow:hidden;font-family:Arial, sans-serif;">'
        '<table style="width:100%;border-collapse:collapse;">'
        '<tr style="background:#00285E;color:#FFFFFF;">'
        '<th style="padding:10px 16px;text-align:left;">PLAYER</th>'
        f'<th style="padding:10px 16px;text-align:center;">{value_col.upper()}</th></tr>'
        f'{rows_html}</table></div>'
    )
    st.markdown(html, unsafe_allow_html=True)
    return df


def load_manual_tally(key):
    return kv_get(key, {})


def add_manual_tally(key, initials, amount):
    data = load_manual_tally(key)
    data[initials] = data.get(initials, 0) + amount
    kv_set(key, data)


