def load_fixture_data():
    return kv_get(FIXTURE_DATA_KEY, {})


def save_fixture_data(key, score=None, logo_filename=None, scorers=None, assists=None, strikes=None):
    data = load_fixture_data()
    entry = data.get(key, {})
    if score is not None:
        entry['score'] = score
    if logo_filename is not None:
        entry['logo'] = logo_filename
    if scorers is not None:
        entry['scorers'] = scorers
    if assists is not None:
        entry['assists'] = assists
    if strikes is not None:
        entry['strikes'] = strikes
    data[key] = entry
    kv_set(FIXTURE_DATA_KEY, data)


def save_logo(uploaded_logo, opponent_name):
    ext = Path(uploaded_logo.name).suffix
    dest = SAVED_LOGOS_DIR / f"{opponent_name.replace(' ', '_')}{ext}"
    dest.write_bytes(uploaded_logo.getvalue())
    return dest.name


def save_uploaded_file(uploaded_file):
    """Save an uploaded file to disk (if not already saved) so it can be reloaded later."""
    dest = SAVED_XML_DIR / uploaded_file.name
    if not dest.exists():
        dest.write_bytes(uploaded_file.getvalue())
    return dest


def list_saved_files():
    return sorted(p.name for p in SAVED_XML_DIR.glob("*.xml"))


def pick_file(label, key):
    """Show an uploader + a dropdown of previously saved files. Returns an open file-like object and its name, or (None, None)."""
    col1, col2 = st.columns([2, 1])
    with col1:
        uploaded = st.file_uploader(label, type="xml", key=f"{key}_upload")
    with col2:
        saved = list_saved_files()
        choice = st.selectbox(
            "...or reuse a saved file", ["(none)"] + saved, key=f"{key}_saved"
        )

    if uploaded is not None:
        save_uploaded_file(uploaded)
        return uploaded, uploaded.name
    elif choice != "(none)":
        path = SAVED_XML_DIR / choice
        return BytesIO(path.read_bytes()), choice
    return None, None


def load_history():
    return kv_get(HISTORY_KEY, [])


def save_match_to_history(match_name, ratings_df):
    history = load_history()
    # replace any existing entry for this match name so re-running doesn't duplicate
    history = [h for h in history if h['match_name'] != match_name]
    history.append({
        'match_name': match_name,
        'date_added': str(date.today()),
        'ratings': ratings_df[['player', 'rating']].to_dict(orient='records')
    })
    kv_set(HISTORY_KEY, history)


def parse_xml(file, source_name):
    """Parse one tagging XML file into a dataframe, keeping every field found."""
    tree = ET.parse(file)
    root = tree.getroot()
    rows = []
    for inst in root.find('ALL_INSTANCES').findall('instance'):
        row = {'source_file': source_name}
        # Grab every child tag under this instance, whatever it's called
        for child in inst:
            row[child.tag] = child.text.strip() if child.text else None
        rows.append(row)
    df = pd.DataFrame(rows)

    # Add minute markers if start/end exist, for readability
    if 'start' in df.columns:
        df['start'] = pd.to_numeric(df['start'], errors='coerce')
        df['start_minute'] = (df['start'] / 60).round(2)
    if 'end' in df.columns:
        df['end'] = pd.to_numeric(df['end'], errors='coerce')
        df['end_minute'] = (df['end'] / 60).round(2)
    if 'start' in df.columns and 'end' in df.columns:
        df['duration_sec'] = (df['end'] - df['start']).round(2)

    return df


def to_excel_bytes(df):
    output = BytesIO()
    with pd.ExcelWriter(output, engine='openpyxl') as writer:
        df.to_excel(writer, index=False, sheet_name='Data')
    return output.getvalue()


def build_word_report(match_title, summary_df, ratings_df):
    from docx import Document
    from docx.shared import Pt, RGBColor
    from docx.enum.text import WD_ALIGN_PARAGRAPH

    doc = Document()

    title = doc.add_heading(f"AFC Wimbledon — Match Report", level=0)
    subtitle = doc.add_heading(match_title, level=1)

    doc.add_heading("Action Summary", level=2)
    table = doc.add_table(rows=1, cols=2)
    table.style = 'Light Grid Accent 1'
    hdr = table.rows[0].cells
    hdr[0].text, hdr[1].text = 'Action', 'Count'
    for _, row in summary_df.iterrows():
        cells = table.add_row().cells
        cells[0].text = str(row['code'])
        cells[1].text = str(row['count'])

    doc.add_heading("Player Ratings", level=2)
    rtable = doc.add_table(rows=1, cols=2)
    rtable.style = 'Light Grid Accent 1'
    hdr = rtable.rows[0].cells
    hdr[0].text, hdr[1].text = 'Player', 'Rating'
    for _, row in ratings_df.iterrows():
        cells = rtable.add_row().cells
        cells[0].text = str(row['player'])
        cells[1].text = str(row['rating'])

    output = BytesIO()
    doc.save(output)
    return output.getvalue()



