    with sub_tabs[3]:
        # ---------- Highlights Reel ----------

        st.divider()
        section_banner("Highlights Reel", "Auto-cut clips from your video using your tagged events")

        st.caption(
            "This uses your video file directly from disk (not uploaded through the browser, since match "
            "footage is usually too large for that). Needs ffmpeg installed \u2014 if you haven't already, run "
            "`brew install ffmpeg` in Terminal once."
        )

        video_path = st.text_input(
            "Full path to your video file (drag the file into Terminal to copy its path, then paste it here)",
            key="video_path"
        )

        highlight_source_file, highlight_source_name = pick_file("Tagged XML for this match", "highlights")

        if video_path and highlight_source_file:
            if not Path(video_path).exists():
                st.error("That video file path doesn't exist. Double check it and try again.")
            else:
                hdf = parse_xml(highlight_source_file, highlight_source_name)
                codes_available = sorted(hdf['code'].unique())
                highlight_codes = st.multiselect(
                    "Which tagged moments should be included in the reel?",
                    options=codes_available,
                    default=[c for c in ['GOAL', 'SHOT ON'] if c in codes_available]
                )
                col1, col2 = st.columns(2)
                with col1:
                    pad_before = st.number_input("Seconds to include BEFORE each moment", value=5.0, step=1.0)
                with col2:
                    pad_after = st.number_input("Seconds to include AFTER each moment", value=3.0, step=1.0)

                if st.button("\U0001F3AC Generate Highlights Reel"):
                    clips = hdf[hdf['code'].isin(highlight_codes)].sort_values('start')
                    if clips.empty:
                        st.warning("No tagged moments match your selection.")
                    else:
                        import subprocess, tempfile, shutil

                        if shutil.which("ffmpeg") is None:
                            st.error("ffmpeg isn't installed. Run `brew install ffmpeg` in Terminal, then try again.")
                            st.stop()

                        with st.spinner(f"Cutting {len(clips)} clips and stitching them together..."):
                            tmpdir = Path(tempfile.mkdtemp())
                            clip_paths = []
                            for i, (_, row) in enumerate(clips.iterrows()):
                                start = max(0, row['start'] - pad_before)
                                duration = (row['end'] - row['start']) + pad_before + pad_after
                                out_path = tmpdir / f"clip_{i:04d}.mp4"
                                subprocess.run([
                                    "ffmpeg", "-y", "-ss", str(start), "-i", video_path,
                                    "-t", str(duration), "-c", "copy", str(out_path)
                                ], capture_output=True)
                                if out_path.exists():
                                    clip_paths.append(out_path)

                            concat_list = tmpdir / "concat.txt"
                            concat_list.write_text("".join(f"file '{p}'\n" for p in clip_paths))

                            output_name = f"{highlight_source_name.replace('.xml', '')}_highlights.mp4"
                            output_path = Path(video_path).parent / output_name
                            subprocess.run([
                                "ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", str(concat_list),
                                "-c", "copy", str(output_path)
                            ], capture_output=True)

                        if output_path.exists():
                            st.success(f"Highlights reel saved to: {output_path}")
                            st.video(str(output_path))
                        else:
                            st.error("Something went wrong generating the reel. Check the video path and try again.")




